\begin{tikzpicture}[x=7mm,y=7mm,font=\fontsize{10}{12}\selectfont]
\draw[black!20,line width=.25pt](-6,-6)grid(6,6);
\draw[->,line width=.5pt](-6,0)--(6.35,0)node[above]{$x$};
\draw[->,line width=.5pt](0,-6)--(0,6.35)node[right]{$y$};
\foreach \x in {-4,-2,0,2,4}{\node[below=2pt]at(\x,-6){$\x$};}
\foreach \y in {-4,-2,2,4}{\node[left=2pt]at(-6,\y){$\y$};}
\begin{scope}\clip(-6,-6)rectangle(6,6);
\draw[line width=.8pt,solid,domain=-6:6]plot(\x,{1*\x});
\draw[line width=.8pt,dashed,domain=-6:6]plot(\x,{2*\x});
\draw[line width=.8pt,dotted,domain=-6:6]plot(\x,{4*\x});
\draw[line width=.8pt,dash dot,domain=-6:6]plot(\x,{-3*\x});
\draw[line width=.8pt,dash dot dot,domain=-6:6]plot(\x,{-4*\x});
\end{scope}
\end{tikzpicture}
